contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 guess) public payable {
        // Fund c with 1 ether so the lock-in payment can be made.
        require(address(this).balance >= 1 ether);
        c.lockInGuess{value: 1 ether}(guess);

        // Record pre-settle observations through public surface.
        uint preSettleBalance = address(c).balance;

        // Revert when calling settle too early: block.number is not greater than
        // the locked-in target block, which is at least the next block.
        bool earlyReverted;
        try c.settle() {
            earlyReverted = false;
        } catch {
            earlyReverted = true;
        }

        // The general rule: either settle reverted (because the target block has
        // not been reached yet), or it succeeded only if the contract already
        // held at least 2 ether before the call. In both cases, the player's
        // lock-in block is cleared to zero by a successful settle.
        assert(
            earlyReverted || preSettleBalance >= 2 ether
        );
    }

    receive() external payable {}
}

