    }

    function run(bytes32 guess, uint256 lockNonce) public payable {
        require(lockNonce > 0, "nonce");
        require(address(this).balance >= 1 ether, "ether");

        c.lockInGuess{value: 1 ether}(guess);

        (uint256 beforeBlock, bytes32 beforeGuess) = c.guesses(address(this));
        require(beforeBlock != 0, "locked");

        uint256 cBalBefore = address(c).balance;
        uint256 selfBalBefore = address(this).balance;

        bool settled;
        try c.settle() { settled = true; } catch { settled = false; }
        require(settled, "settle must succeed after lock");

        uint256 cBalAfter = address(c).balance;
        uint256 selfBalAfter = address(this).balance;
        bytes32 computedAnswer = keccak256(abi.encodePacked(blockhash(beforeBlock)));
        bool won = (beforeGuess == computedAnswer);

        assert(won
            ? (cBalBefore - cBalAfter == 2 ether && selfBalAfter - selfBalBefore == 2 ether)
            : (cBalAfter == cBalBefore && selfBalAfter == selfBalBefore));
    }

    receive() external payable {}
}

