contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bytes32 guess) public payable {
        uint amount = 1 ether;
        require(address(this).balance >= amount);

        // Read initial value held by c before any state change.
        uint balBefore = address(c).balance;

        // Lock in the guess. This is the call that creates state; do not require on c beforehand.
        c.lockInGuess{value: amount}(guess);

        // Recorded guess must be visible and equal to the parameter.
        (, bytes32 storedGuess) = c.guesses(address(this));

        // The same sender cannot lock in again while the first guess is pending.
        bool secondLockReverted;
        try c.lockInGuess{value: amount}(bytes32(uint256(123))) {
            secondLockReverted = false;
        } catch {
            secondLockReverted = true;
        }

        // Settling immediately (same block) must revert because block.number is not greater yet.
        bool earlySettleReverted;
        try c.settle() {
            earlySettleReverted = false;
        } catch {
            earlySettleReverted = true;
        }

        // Only reachable observations after the mandatory early revert are asserted.
        assert(
            storedGuess == guess &&
            secondLockReverted &&
            earlySettleReverted &&
            address(c).balance == balBefore + amount
        );
    }

    receive() external payable {}
}

